create table if not exists instrument.v39_h1_totals as select ctx,sum(n)::bigint as n from instrument.v39_h1_counts group by ctx; create unique index if not exists v39_h1_totals_idx on instrument.v39_h1_totals(ctx); create table if not exists instrument.v39_h2_totals as select ctx,sum(n)::bigint as n from instrument.v39_h2_counts group by ctx; create unique index if not exists v39_h2_totals_idx on instrument.v39_h2_totals(ctx); create table if not exists instrument.v39_h3_totals as select ctx,sum(n)::bigint as n from instrument.v39_h3_counts group by ctx; create unique index if not exists v39_h3_totals_idx on instrument.v39_h3_totals(ctx); create table if not exists instrument.v39_h4_totals as select ctx,sum(n)::bigint as n from instrument.v39_h4_counts group by ctx; create unique index if not exists v39_h4_totals_idx on instrument.v39_h4_totals(ctx);